def main():
    # แค่ต่อท้าย: ไม่ใช้ V.main() เพราะมันเขียนทับค่า sn/tr ที่แก้มือไปแล้ว และดึงที่ที่ลบแล้วกลับมา
    text = V.DATA.read_text(encoding="utf-8")
    head, body = text.split("window.PLACES = ", 1)
    places = json.loads(body.rstrip().rstrip(";"))
    region = dict(re.findall(r'id: "(\w+)",[^}]*?region: "([^"]+)"', (V.ROOT / "data" / "hubs.js").read_text(encoding="utf-8")))
    have = {p["ja"] for p in places}
    nid = max(p["id"] for p in places) + 1
    for n in MORE:
        if n["ja"] in have:
            continue
        n = {k: v for k, v in n.items() if v not in (None, "", {}) or k == "caution"}
        n.pop("wiki", None)
        lat, lng = COORD[n["ja"]]
        n.update(id=nid, region=region[n["hub"]], feeYen=int(re.search(r"¥([\d,]+)", n["fee"]).group(1).replace(",", "")) if "¥" in n["fee"] else 0,
                 lat=lat, lng=lng, acc="ประมาณ", checked="2026-11")
        places.append(n)
        nid += 1
    V.DATA.write_text(head + "window.PLACES = " + json.dumps(places, ensure_ascii=False, indent=1) + ";\n", encoding="utf-8")
    print("total", len(places))


if __name__ == "__main__":
    main()
